	"testing"

	"github.com/hkjang/ai-admin/internal/database"
	"github.com/hkjang/ai-admin/internal/secrets"
)

// A provider that stops writing in the middle of an answer must not look like a
// provider that finished one: the caller has to see the request fail rather than
// keep a half-written reply that reads as a complete model response.
func TestChatAnswerCutShortIsNotDeliveredAsComplete(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}

	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{9}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	service := httptest.NewServer(handler)
	defer service.Close()
	session := signIn(t, handler)

	// The synthetic provider sends the first token and then drops the connection,
	// exactly as an upstream that dies mid-answer does.
	const partial = "data: {\"choices\":[{\"delta\":{\"content\":\"답변 시작\"}}]}\n\n"
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/event-stream")
		w.WriteHeader(http.StatusOK)
		_, _ = io.WriteString(w, partial)
		_ = http.NewResponseController(w).Flush()
		connection, _, hijackErr := http.NewResponseController(w).Hijack()
		if hijackErr != nil {
			t.Errorf("hijack synthetic provider connection: %v", hijackErr)
			return
		}
		_ = connection.Close()
	}))
	defer upstream.Close()

	created := session.do(t, handler, http.MethodPost, "/api/v1/ai/providers", map[string]any{
		"name": "잘리는 공급자", "type": "openai-compatible", "baseUrl": upstream.URL,
		"defaultModel": "test-model", "contextWindow": 131072, "maxOutputTokens": 8192,
	})
	if created.Code != http.StatusCreated {
		t.Fatalf("provider status=%d body=%s", created.Code, created.Body.String())
	}
	var providerEnvelope struct {
		Data struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.Unmarshal(created.Body.Bytes(), &providerEnvelope); err != nil {
		t.Fatal(err)
	}

	body, err := json.Marshal(map[string]any{
		"provider_id": providerEnvelope.Data.ID,
		"model":       "test-model",
		"stream":      true,
		"messages":    []map[string]string{{"role": "user", "content": "안녕하세요"}},
	})
	if err != nil {
		t.Fatal(err)
	}
	request, err := http.NewRequest(http.MethodPost, service.URL+"/v1/chat/completions", bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("X-CSRF-Token", session.csrf)
	for _, cookie := range session.cookies {
		request.AddCookie(cookie)
	}
	response, err := service.Client().Do(request)
	if err != nil {
		t.Fatalf("chat request: %v", err)
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		t.Fatalf("chat status=%d", response.StatusCode)
	}
	relayed, readErr := io.ReadAll(response.Body)
	if readErr == nil {
		t.Fatalf("a chat answer cut short was delivered as a complete response: %q", relayed)
	}
	if delivered := string(relayed); delivered != "" && !strings.HasPrefix(partial, delivered) {
		t.Fatalf("relayed body is not a prefix of what the provider sent: %q", delivered)
	}

	var reason string
	if err := db.Pool.QueryRow(ctx, `SELECT COALESCE(details->>'reason','') FROM ai_admin.audit_event
WHERE action='ai.chat' AND result='failure' ORDER BY occurred_at DESC LIMIT 1`).Scan(&reason); err != nil {
		t.Fatalf("the truncated answer was not audited as a failure: %v", err)
	}
	if reason != "upstream_read_failed" {
		t.Fatalf("audited reason=%q want=upstream_read_failed", reason)
	}
}
