package server

import (
	"context"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

// failingReader hands out one chunk and then fails the way an upstream that
// hangs up in the middle of an answer does.
type failingReader struct {
	chunk string
	err   error
	sent  bool
}

func (f *failingReader) Read(p []byte) (int, error) {
	if !f.sent {
		f.sent = true
		return copy(p, f.chunk), nil
	}
	return 0, f.err
}

// unflushableWriter is a ResponseWriter without Flush, which is how a caller
// that cannot receive streamed chunks looks to the relay.
type unflushableWriter struct{ header http.Header }

func (u *unflushableWriter) Header() http.Header {
	if u.header == nil {
		u.header = http.Header{}
	}
	return u.header
}
func (u *unflushableWriter) Write(p []byte) (int, error) { return len(p), nil }
func (u *unflushableWriter) WriteHeader(int)             {}

// brokenWriter is a caller that stopped reading the response.
type brokenWriter struct{ unflushableWriter }

func (b *brokenWriter) Write([]byte) (int, error) { return 0, errors.New("broken pipe") }

// A relayed chat answer is only complete when the whole upstream body reached
// the caller; every other outcome has to be reported with the reason it stopped
// so the audit trail does not record a cut-off answer as a finished one.
func TestRelayChatBodyReportsWhyTheAnswerStopped(t *testing.T) {
	cancelled, cancel := context.WithCancel(context.Background())
	cancel()
	expired, expire := context.WithDeadline(context.Background(), time.Now().Add(-time.Second))
	defer expire()

	cases := []struct {
		name      string
		ctx       context.Context
		body      io.Reader
		writer    http.ResponseWriter
		stream    bool
		completed bool
		reason    string
		written   string
	}{
		{
			name:      "whole body delivered",
			ctx:       context.Background(),
			body:      strings.NewReader("data: {\"choices\":[]}\n\ndata: [DONE]\n\n"),
			stream:    true,
			completed: true,
			written:   "data: {\"choices\":[]}\n\ndata: [DONE]\n\n",
		},
		{
			name:    "upstream hangs up mid answer",
			ctx:     context.Background(),
			body:    &failingReader{chunk: "data: {\"choices\":[{\"delta\":{\"content\":\"안녕\"}}]}\n\n", err: io.ErrUnexpectedEOF},
			stream:  true,
			reason:  "upstream_read_failed",
			written: "data: {\"choices\":[{\"delta\":{\"content\":\"안녕\"}}]}\n\n",
		},
		{
			name:    "provider timeout",
			ctx:     expired,
			body:    &failingReader{chunk: "partial", err: context.DeadlineExceeded},
			stream:  true,
			reason:  "upstream_timeout",
			written: "partial",
		},
		{
			name:    "request abandoned",
			ctx:     cancelled,
			body:    &failingReader{chunk: "partial", err: context.Canceled},
			stream:  true,
			reason:  "request_cancelled",
			written: "partial",
		},
		{
			name:   "caller stopped reading",
			ctx:    context.Background(),
			body:   strings.NewReader("data: {}\n\n"),
			writer: &brokenWriter{},
			stream: true,
			reason: "client_write_failed",
		},
		{
			name:   "caller cannot receive streamed chunks",
			ctx:    context.Background(),
			body:   strings.NewReader("data: {}\n\n"),
			writer: &unflushableWriter{},
			stream: true,
			reason: "client_flush_failed",
		},
		{
			name:      "non-streaming body delivered",
			ctx:       context.Background(),
			body:      strings.NewReader(`{"choices":[]}`),
			completed: true,
			written:   `{"choices":[]}`,
		},
	}

	for _, testCase := range cases {
		t.Run(testCase.name, func(t *testing.T) {
			recorder := httptest.NewRecorder()
			var writer http.ResponseWriter = recorder
			if testCase.writer != nil {
				writer = testCase.writer
			}
			relay := relayChatBody(testCase.ctx, writer, http.NewResponseController(writer), testCase.body, testCase.stream)
			if relay.completed != testCase.completed || relay.reason != testCase.reason {
				t.Fatalf("relay=%+v want completed=%v reason=%q", relay, testCase.completed, testCase.reason)
			}
			if testCase.writer == nil && recorder.Body.String() != testCase.written {
				t.Fatalf("relayed body=%q want=%q", recorder.Body.String(), testCase.written)
			}
		})
	}
}

