// A non-streaming chat answer carries the same promise the streaming one does:
// what leaves the console origin is JSON. A provider that answers with HTML or
// plain text must fail the request instead of having its media type re-emitted
// to the browser that trusts this origin.
func TestChatNonStreamingResponseContentTypeContract(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}

	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{9}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	service := httptest.NewServer(handler)
	defer service.Close()
	session := signIn(t, handler)

	const answer = `{"id":"chatcmpl-1","choices":[{"message":{"role":"assistant","content":"안녕하세요"}}]}`
	var mu sync.Mutex
	upstreamContentType := "application/json"
	setUpstreamContentType := func(value string) {
		mu.Lock()
		defer mu.Unlock()
		upstreamContentType = value
	}
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		value := upstreamContentType
		mu.Unlock()
		if value == "" {
			// Present but empty suppresses net/http's own content sniffing, so the
			// relay really sees a response without a Content-Type header.
			w.Header()["Content-Type"] = nil
		} else {
			w.Header().Set("Content-Type", value)
		}
		w.WriteHeader(http.StatusOK)
		_, _ = io.WriteString(w, answer)
	}))
	defer upstream.Close()

	created := session.do(t, handler, http.MethodPost, "/api/v1/ai/providers", map[string]any{
		"name": "비스트리밍 공급자", "type": "openai-compatible", "baseUrl": upstream.URL,
		"defaultModel": "test-model", "contextWindow": 131072, "maxOutputTokens": 8192,
	})
	if created.Code != http.StatusCreated {
		t.Fatalf("provider status=%d body=%s", created.Code, created.Body.String())
	}
	var providerEnvelope struct {
		Data struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.Unmarshal(created.Body.Bytes(), &providerEnvelope); err != nil {
		t.Fatal(err)
	}

	// "stream": false is explicit: leaving it out lets the provider's streamDefault
	// and the ai.stream_default setting pick the streaming path instead.
	chat := func(t *testing.T) *http.Response {
		t.Helper()
		body, err := json.Marshal(map[string]any{
			"provider_id": providerEnvelope.Data.ID,
			"model":       "test-model",
			"stream":      false,
			"messages":    []map[string]string{{"role": "user", "content": "안녕하세요"}},
		})
		if err != nil {
			t.Fatal(err)
		}
		request, err := http.NewRequest(http.MethodPost, service.URL+"/v1/chat/completions", bytes.NewReader(body))
		if err != nil {
			t.Fatal(err)
		}
		request.Header.Set("Content-Type", "application/json")
		request.Header.Set("X-CSRF-Token", session.csrf)
		for _, cookie := range session.cookies {
			request.AddCookie(cookie)
		}
		response, err := service.Client().Do(request)
		if err != nil {
			t.Fatalf("chat request: %v", err)
		}
		return response
	}
	latestChatAudit := func(t *testing.T) (result, reason string) {
		t.Helper()
		if err := db.Pool.QueryRow(ctx, `SELECT result, COALESCE(details->>'reason','') FROM ai_admin.audit_event
WHERE action='ai.chat' ORDER BY id DESC LIMIT 1`).Scan(&result, &reason); err != nil {
			t.Fatalf("no ai.chat audit event was written: %v", err)
		}
		return result, reason
	}

	accepted := []struct {
		name     string
		upstream string
	}{
		{name: "plain_json", upstream: "application/json"},
		{name: "json_with_parameter_and_mixed_case", upstream: "Application/JSON; charset=utf-8"},
		{name: "structured_json_suffix", upstream: "application/vnd.provider+json"},
		{name: "no_content_type_header", upstream: ""},
	}
	for _, testCase := range accepted {
		t.Run(testCase.name, func(t *testing.T) {
			setUpstreamContentType(testCase.upstream)
			response := chat(t)
			defer response.Body.Close()
			relayed, readErr := io.ReadAll(response.Body)
			if readErr != nil {
				t.Fatalf("read relayed body: %v", readErr)
			}
			if response.StatusCode != http.StatusOK {
				t.Fatalf("status=%d want=200 body=%s", response.StatusCode, relayed)
			}
			if string(relayed) != answer {
				t.Fatalf("relayed body=%q want=%q", relayed, answer)
			}
			if got := response.Header.Get("Content-Type"); got != "application/json; charset=utf-8" {
				t.Fatalf("Content-Type=%q want=%q (upstream sent %q)", got, "application/json; charset=utf-8", testCase.upstream)
			}
			if result, reason := latestChatAudit(t); result != "success" || reason != "" {
				t.Fatalf("audited result=%q reason=%q want success with no reason", result, reason)
			}
		})
	}

	rejected := []struct {
		name     string
		upstream string
	}{
		{name: "html_is_rejected", upstream: "text/html; charset=utf-8"},
		{name: "plain_text_is_rejected", upstream: "text/plain"},
		{name: "unparsable_content_type_is_rejected", upstream: "application/json; charset"},
	}
	for _, testCase := range rejected {
		t.Run(testCase.name, func(t *testing.T) {
			setUpstreamContentType(testCase.upstream)
			response := chat(t)
			defer response.Body.Close()
			relayed, readErr := io.ReadAll(response.Body)
			if readErr != nil {
				t.Fatalf("read rejection body: %v", readErr)
			}
			if response.StatusCode != http.StatusBadGateway {
				t.Fatalf("status=%d want=502 body=%s", response.StatusCode, relayed)
			}
			if strings.Contains(response.Header.Get("Content-Type"), "text/html") ||
				strings.Contains(response.Header.Get("Content-Type"), "text/plain") {
				t.Fatalf("upstream media type leaked into the response Content-Type=%q", response.Header.Get("Content-Type"))
			}
			if strings.Contains(string(relayed), "안녕하세요") {
				t.Fatalf("a non-JSON provider body reached the caller: %q", relayed)
			}
			var envelope struct {
				Error struct {
					Code string `json:"code"`
				} `json:"error"`
			}
			if err := json.Unmarshal(relayed, &envelope); err != nil {
				t.Fatalf("rejection body is not a JSON error envelope: %v (%q)", err, relayed)
			}
			if envelope.Error.Code != "ai_response_invalid" {
				t.Fatalf("error code=%q want=ai_response_invalid", envelope.Error.Code)
			}
			result, reason := latestChatAudit(t)
			if result != "failure" || reason != "invalid_response_content_type" {
				t.Fatalf("audited result=%q reason=%q want failure/invalid_response_content_type", result, reason)
			}
		})
	}
}
}

func (s *Server) deleteProvider(w http.ResponseWriter, r *http.Request) {
	id, ok := parseUUIDParameter(w, r, "id")
	if !ok {
		return
	}
	item, err := s.loadProvider(r.Context(), id)
	if errors.Is(err, errNotFound) {
		writeError(w, http.StatusNotFound, "provider_not_found", "AI 공급자를 찾을 수 없습니다.")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "provider_delete_failed", "AI 공급자를 불러오지 못했습니다.")
		return
	}
	expectedText := strings.TrimSpace(r.URL.Query().Get("expectedUpdatedAt"))
	expectedUpdatedAt, parseErr := time.Parse(time.RFC3339Nano, expectedText)
	if parseErr != nil {
		writeError(w, http.StatusBadRequest, "provider_version_required", "최신 공급자 버전으로 새로 고침한 뒤 다시 시도해 주세요.")
		return
	}
	if !expectedUpdatedAt.Equal(item.UpdatedAt) {
		writeError(w, http.StatusConflict, "provider_conflict", "AI 공급자 설정이 다른 요청에서 변경되었습니다. 새로 고침 후 다시 시도해 주세요.")
		return
	}
	p := principalFrom(r.Context())
	if s.workflowRequired(r.Context(), "ai_provider_change") {
		if s.stringSetting(r.Context(), "ai.default_provider_id", "") == id.String() {
			writeError(w, http.StatusConflict, "provider_is_default", "기본 AI 공급자는 삭제할 수 없습니다. 시스템 설정에서 다른 기본 공급자를 먼저 선택해 주세요.")
			return
		}
		approvalID, err := s.createApprovalRecord(r.Context(), "ai_provider_change", p.ID, "AI 공급자 삭제: "+item.Name, map[string]any{
			"operation": "ai_provider.delete", "providerId": id, "expectedUpdatedAt": expectedUpdatedAt,
		}, nil)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "approval_create_failed", "AI 공급자 변경 승인 요청을 만들지 못했습니다.")
			return
		}
		s.audit(r, p, "ai_provider.request", "approval_request", approvalID.String(), "success", map[string]any{"operation": "delete", "providerId": id})
		writeData(w, http.StatusAccepted, map[string]any{"status": "pending_approval", "approvalId": approvalID, "resourceId": id})
		return
	}
	tx, err := s.db.Pool.Begin(r.Context())
	if err != nil {
		writeError(w, http.StatusInternalServerError, "provider_delete_failed", "AI 공급자 삭제를 시작하지 못했습니다.")
		return
	}
	defer func() { _ = tx.Rollback(r.Context()) }()
	if err := lockProviderDeletion(r.Context(), tx, id, expectedUpdatedAt); err != nil {
		if errors.Is(err, errProviderDefault) {
			writeError(w, http.StatusConflict, "provider_is_default", "기본 AI 공급자는 삭제할 수 없습니다. 시스템 설정에서 다른 기본 공급자를 먼저 선택해 주세요.")
		} else if errors.Is(err, errProviderStale) {
			writeError(w, http.StatusConflict, "provider_conflict", "AI 공급자 설정이 다른 요청에서 변경되었거나 삭제되었습니다. 새로 고침 후 다시 시도해 주세요.")
		} else {
			writeError(w, http.StatusInternalServerError, "provider_delete_failed", "AI 공급자 설정을 확인하지 못했습니다.")
		}
		return
	}
	result, err := tx.Exec(r.Context(), `DELETE FROM ai_admin.ai_provider WHERE id=$1`, id)
	if err != nil {
		writeError(w, http.StatusConflict, "provider_in_use", "사용 중인 AI 공급자는 삭제할 수 없습니다.")
		return
	}
	if result.RowsAffected() == 0 {
		writeError(w, http.StatusConflict, "provider_conflict", "AI 공급자 설정이 다른 요청에서 변경되었거나 삭제되었습니다. 새로 고침 후 다시 시도해 주세요.")
		return
	}
	if err := tx.Commit(r.Context()); err != nil {
		writeError(w, http.StatusInternalServerError, "provider_delete_failed", "AI 공급자를 삭제하지 못했습니다.")
		return
	}
	s.audit(r, p, "ai_provider.delete", "ai_provider", id.String(), "success", nil)
	w.WriteHeader(http.StatusNoContent)
}

func providerChangePayload(operation string, id uuid.UUID, request providerRequest) map[string]any {
	// API keys deliberately never enter the JSON approval payload. When present,
	// createApprovalRecord stores the plaintext in its separate encrypted column.
	request.APIKey = nil
	raw, _ := json.Marshal(request)
	payload := map[string]any{}
	_ = json.Unmarshal(raw, &payload)
	delete(payload, "apiKey")
	payload["operation"] = operation
	payload["providerId"] = id.String()
	return payload
}

func (s *Server) testProvider(w http.ResponseWriter, r *http.Request) {
	id, ok := parseUUIDParameter(w, r, "id")
	if !ok {
		return
	}
	item, err := s.loadProvider(r.Context(), id)
	if errors.Is(err, errNotFound) {
		writeError(w, http.StatusNotFound, "provider_not_found", "AI 공급자를 찾을 수 없습니다.")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "provider_test_failed", "공급자 설정을 불러오지 못했습니다.")
		return
	}
	start := time.Now()
	ctx, cancel := context.WithTimeout(r.Context(), 15*time.Second)
	defer cancel()
	request, _ := http.NewRequestWithContext(ctx, http.MethodGet, providerURL(item.BaseURL, "models"), nil)
	if err := s.applyProviderAuth(request, item); err != nil {
		p := principalFrom(r.Context())
		s.audit(r, p, "ai_provider.test", "ai_provider", id.String(), "failure", map[string]any{"reason": "provider_credentials_unavailable"})
		writeError(w, http.StatusServiceUnavailable, "provider_credentials_unavailable", "AI 공급자 인증 정보를 복호화하지 못했습니다. 암호화 키와 공급자 설정을 확인해 주세요.")
		return
	}
	client := *s.client
	client.Timeout = 15 * time.Second
	response, err := client.Do(request)
	if err != nil {
		writeError(w, http.StatusBadGateway, "provider_unreachable", "AI 공급자에 연결하지 못했습니다.", err.Error())
		return
	}
	defer response.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(response.Body, 1<<20))
	if response.StatusCode < 200 || response.StatusCode >= 300 {
		writeError(w, http.StatusBadGateway, "provider_rejected", fmt.Sprintf("AI 공급자가 HTTP %d로 응답했습니다.", response.StatusCode))
		return
	}
	p := principalFrom(r.Context())
	s.audit(r, p, "ai_provider.test", "ai_provider", id.String(), "success", map[string]any{"latencyMs": time.Since(start).Milliseconds()})
	writeData(w, http.StatusOK, map[string]any{"connected": true, "latencyMs": time.Since(start).Milliseconds()})
}

func (s *Server) loadProvider(ctx context.Context, id uuid.UUID) (provider, error) {
	var item provider
	var models []byte
	err := s.db.Pool.QueryRow(ctx, `SELECT id,name,provider_type,base_url,default_model,available_models,
context_window,max_output_tokens,stream_default,enabled,timeout_seconds,encrypted_api_key IS NOT NULL,
created_at,updated_at,encrypted_api_key FROM ai_admin.ai_provider WHERE id=$1`, id).Scan(
		&item.ID, &item.Name, &item.Type, &item.BaseURL, &item.DefaultModel, &models, &item.ContextWindow, &item.MaxOutputTokens, &item.StreamDefault, &item.Enabled, &item.TimeoutSeconds, &item.KeyConfigured, &item.CreatedAt, &item.UpdatedAt, &item.EncryptedAPIKey,
	)
	if errors.Is(err, pgx.ErrNoRows) {
		return provider{}, errNotFound
	}
	if err != nil {
		return provider{}, err
	}
	_ = json.Unmarshal(models, &item.AvailableModels)
	return item, nil
}

func normalizeProviderRequest(request *providerRequest, creating bool) {
	request.Name = strings.TrimSpace(request.Name)
	request.Type = strings.TrimSpace(request.Type)
	request.BaseURL = strings.TrimRight(strings.TrimSpace(request.BaseURL), "/")
	request.DefaultModel = strings.TrimSpace(request.DefaultModel)
	// 읽는 쪽(/api/v1/models, chatCompletions)이 이미 uniqueStrings로 다듬으므로
	// 저장하기 전에 같은 규칙을 적용해 공백·중복·빈 항목이 쌓이지 않게 한다.
	request.AvailableModels = uniqueStrings(request.AvailableModels)
	if request.Type == "" {
		request.Type = "openai-compatible"
	}
	if request.ContextWindow == 0 {
		request.ContextWindow = 131072
	}
	if request.MaxOutputTokens == 0 {
		request.MaxOutputTokens = 8192
	}
	if request.TimeoutSeconds == 0 {
		request.TimeoutSeconds = 120
	}
	if request.StreamDefault == nil {
		value := true
		request.StreamDefault = &value
	}
	if request.Enabled == nil {
		value := true
		request.Enabled = &value
	}
	if creating {
		request.ExpectedUpdatedAt = nil
	}
}

func mergeProviderRequest(request *providerRequest, current provider) {
	if request.Name == "" {
		request.Name = current.Name
	}
	if request.Type == "" {
		request.Type = current.Type
	}
	if request.BaseURL == "" {
		request.BaseURL = current.BaseURL
	}
	if request.DefaultModel == "" {
		request.DefaultModel = current.DefaultModel
	}
	if request.AvailableModels == nil {
		request.AvailableModels = current.AvailableModels
	}
	if request.ContextWindow == 0 {
		request.ContextWindow = current.ContextWindow
	}
	if request.MaxOutputTokens == 0 {
		request.MaxOutputTokens = current.MaxOutputTokens
	}
	if request.StreamDefault == nil {
		value := current.StreamDefault
		request.StreamDefault = &value
	}
	if request.Enabled == nil {
		value := current.Enabled
		request.Enabled = &value
	}
	if request.TimeoutSeconds == 0 {
		request.TimeoutSeconds = current.TimeoutSeconds
	}
}
